            cJSON_AddNumberToObject(j, "FEMALECOUNT", x->femalecount);
            cJSON_AddNumberToObject(j, "FIXERCOUNT", x->fixercount);
            if (NULL != x->governingname) {
                cJSON_AddStringToObject(j, "GOVERNINGNAME", x->governingname);
            }
            else {
                cJSON_AddStringToObject(j, "GOVERNINGNAME", "");
            }
            if (NULL != x->history) {
                cJSON_AddStringToObject(j, "HISTORY", x->history);
            }
            else {
                cJSON_AddStringToObject(j, "HISTORY", "");
            }
            cJSON_AddNumberToObject(j, "KEEPERCOUNT", x->keepercount);
            cJSON_AddNumberToObject(j, "MACOUNT", x->macount);
            cJSON_AddNumberToObject(j, "MALECOUNT", x->malecount);
            cJSON_AddNumberToObject(j, "MAXLVL", x->maxlvl);
            cJSON_AddNumberToObject(j, "METACOUNT", x->metacount);
            cJSON_AddNumberToObject(j, "MINLVL", x->minlvl);
            cJSON_AddNumberToObject(j, "MONSTERCOUNT", x->monstercount);
            if (NULL != x->name) {
                cJSON_AddStringToObject(j, "NAME", x->name);
            }
            else {
                cJSON_AddStringToObject(j, "NAME", "");
            }
            cJSON_AddNumberToObject(j, "NANOCOUNT", x->nanocount);
            cJSON_AddNumberToObject(j, "NANORACECOUNT", x->nanoracecount);
            cJSON_AddNumberToObject(j, "NEUTERCOUNT", x->neutercount);
            cJSON_AddNumberToObject(j, "NUMMEMBERS", x->nummembers);
